+      </p>
+    </section>
+
+    <section class="faq-card" aria-label="Cat frequently asked questions">
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-1" id="question-1">
+          Why do cats purr?
